const text      = $('Normalizar Input').item.json.text;
const device_id = $('Normalizar Input').item.json.device_id;

// Sesiones
const sessions = $('DynamoDB Sesiones').item.json.Items ?? [];
const totalDist   = sessions.reduce((a, s) => a + parseFloat(s.distance_km?.N ?? 0), 0);
const totalHours  = sessions.reduce((a, s) => a + parseFloat(s.duration_min?.N ?? 0), 0) / 60;
const maxSpeed    = Math.max(...sessions.map(s => parseFloat(s.speed_max_kmh?.N ?? 0)));
const avgDriving  = sessions.length > 0
  ? sessions.reduce((a, s) => a + parseFloat(s.driving_score?.N ?? 0), 0) / sessions.length
  : 0;
const avgEffic    = sessions.length > 0
  ? sessions.reduce((a, s) => a + parseFloat(s.efficiency_score?.N ?? 0), 0) / sessions.length
  : 0;

const routeDist = { urbana: 0, carretera: 0, montana: 0, mixta: 0 };
sessions.forEach(s => {
  const rt = s.route_type?.S ?? 'mixta';
  routeDist[rt] = (routeDist[rt] ?? 0) + parseFloat(s.distance_km?.N ?? 0);
});

// Predicciones
const preds = $('DynamoDB Predicciones').item.json.Items ?? [];
const latestPred = preds[0] ?? {};

// Mantenimiento
const maint = $('DynamoDB Mantenimiento').item.json.Items ?? [];
const latestMaint = maint[0] ?? {};

const stats = {
  resumen: {
    total_sesiones:      sessions.length,
    distancia_total_km:  totalDist.toFixed(1),
    horas_totales:       totalHours.toFixed(1),
    velocidad_max_km:    isFinite(maxSpeed) ? maxSpeed.toFixed(1) : '0',
    score_conduccion_avg: avgDriving.toFixed(0),
    score_eficiencia_avg: avgEffic.toFixed(0),
  },
  rutas: routeDist,
  mantenimiento_actual: {
    aceite_km:         latestMaint.remaining_km_oil?.N ?? 'N/A',
    freno_del_km:      latestMaint.remaining_km_brake_front?.N ?? 'N/A',
    freno_tra_km:      latestMaint.remaining_km_brake_rear?.N ?? 'N/A',
    cadena_km:         latestMaint.remaining_km_chain?.N ?? 'N/A',
    llanta_del_km:     latestMaint.remaining_km_tire_front?.N ?? 'N/A',
    llanta_tra_km:     latestMaint.remaining_km_tire_rear?.N ?? 'N/A',
    urgencia:          latestMaint.urgency?.S ?? 'ok',
    componente_critico: latestMaint.most_critical_component?.S ?? 'ninguno',
  },
  ultimas_predicciones: preds.slice(0, 3).map(p => ({
    session_id:     p.session_id?.S ?? '',
    urgencia:       p.urgency?.S ?? 'ok',
    componente:     p.most_critical_component?.S ?? '',
    km_restantes:   p.most_critical_remaining_km?.N ?? '0',
  })),
  ultimas_5_sesiones: sessions.slice(0, 5).map(s => ({
    fecha:        s.date?.S ?? 'N/A',
    distancia_km: s.distance_km?.N ?? '0',
    duracion_min: s.duration_min?.N ?? '0',
    score:        s.driving_score?.N ?? '0',
    eficiencia:   s.efficiency_score?.N ?? '0',
    ruta:         s.route_type?.S ?? 'N/A',
  })),
};

return [{ json: { text, device_id, stats: JSON.stringify(stats, null, 2) } }];

let body = $json.body ?? $json;
if (typeof body === 'string') body = JSON.parse(body);
let response = body;
if (typeof body.body === 'string') response = JSON.parse(body.body);

const stats = $('Calcular Estadísticas').item.json.stats;

return [{
  json: {
    response_text: response.response_text ?? 'No pude generar el análisis',
    intent:        response.intent ?? 'HISTORY',
    language:      response.language ?? 'es',
    stats:         stats,
    success:       true,
  }
}];
